// ワイヤの調整
void CACal::AdjWireChen(int w, WDEF *op, WDEF *np)
{
	CWGroup *cp = WList.GetCW(w);		// エレメントの参照を得る
	if( cp == NULL ) return;

	WREF *rp = cp->pB;
	int i;
	for( i = 0; i < cp->bcnt; i++, rp++ ){
		if( w != rp->ref ){
			if( (np->X1 != op->X1) || (np->Y1 != op->Y1) || (np->Z1 != op->Z1) ){
				::AdjWireChen(rp->wp, op->X1, op->Y1, op->Z1, np->X1, np->Y1, np->Z1);
			}
			if( (np->X2 != op->X2) || (np->Y2 != op->Y2) || (np->Z2 != op->Z2) ){
				::AdjWireChen(rp->wp, op->X2, op->Y2, op->Z2, np->X2, np->Y2, np->Z2);
			}
		}
	}
}
// 単純ワイヤ
void CACal::SetParaWire(AVAL *ap, double d)
{
	WDEF *wp = &WList.wdef[ap->Pos];
	WDEF OldW;
	memcpy(&OldW, wp, sizeof(WDEF));
	switch(ap->SubPos){
		case 0:
			wp->Y1 = d;
			break;
		case 1:
			wp->Z1 = d;
			break;
		case 2:
			wp->Y2 = d;
			break;
		case 3:
			wp->Z2 = d;
			break;
		case 4:
			wp->R = d;
			break;
		case 5:
			wp->X1 = d - WList.GetXAbs(ap->Pos);
			break;
		case 6:
			wp->X2 = d - WList.GetXAbs(ap->Pos);
			break;
	}
	AdjWireChen(ap->Pos, &OldW, wp);
}
// 極座標ワイヤ
void CACal::SetParaWireP(AVAL *ap, double d)
{
	WDEF *wp = &WList.wdef[ap->Pos];
	WDEF OldW;
	memcpy(&OldW, wp, sizeof(WDEF));
	double WL;
	double XYD;
	double YZD;
	GetWirePoll(WL, XYD, YZD, wp);
	int	sw = 0;
	switch(ap->SubPos){
		case 0:		// ワイヤ長（始点基準）
			WL = d;
			sw = 0;
			break;
		case 1:		// ワイヤ長（終点基準）
			WL = d;
			sw = 1;
			break;
		case 2:		// ワイヤ長（中心基準）
			WL = d;
			sw = 2;
			break;
		case 3:		// 径度（始点基準）
			XYD = d;
			sw = 0;
			break;
		case 4:		// 径度（終点基準）
			XYD = d;
			sw = 1;
			break;
		case 5:		// 径度（中心基準）
			XYD = d;
			sw = 2;
			break;
		case 6:		// 天頂角（始点基準）
			YZD = d;
			sw = 0;
			break;
		case 7:		// 天頂角（終点基準）
			YZD = d;
			sw = 1;
			break;
		case 8:		// 天頂角（中心基準）
			YZD = d;
			sw = 2;
			break;
	}
	double XX = WL * sin(YZD*PAI/180.0) * cos(XYD*PAI/180.0);
	double YY = WL * sin(YZD*PAI/180.0) * sin(XYD*PAI/180.0);
	double ZZ = WL * cos(YZD*PAI/180.0);
	double XC = (wp->X1 + wp->X2)/2.0;
	double YC = (wp->Y1 + wp->Y2)/2.0;
	double ZC = (wp->Z1 + wp->Z2)/2.0;
	switch(sw){
		case 0:		// 始点
			wp->X2 = wp->X1 + XX;
			wp->Y2 = wp->Y1 + YY;
			wp->Z2 = wp->Z1 + ZZ;
			break;
		case 1:		// 終点
			wp->X1 = wp->X2 - XX;
			wp->Y1 = wp->Y2 - YY;
			wp->Z1 = wp->Z2 - ZZ;
			break;
		case 2:		// 中心
			XX /= 2.0;
			YY /= 2.0;
			ZZ /= 2.0;
			wp->X1 = XC - XX;
			wp->Y1 = YC - YY;
			wp->Z1 = ZC - ZZ;
			wp->X2 = XC + XX;
			wp->Y2 = YC + YY;
			wp->Z2 = ZC + ZZ;
			break;
	}
	AdjWireChen(ap->Pos, &OldW, wp);
}

void CACal::SetParaEle(AVAL *ap, double d)
{
	CWGroup	*cp = &WList.List[ap->Pos];
	switch(ap->SubPos){
		case 0:		// 間隔
			WList.Intval[ap->Pos] = d;
			break;
		case 1:		// 横幅
			cp->SetWidth(d);
			break;
		case 2:		// 縦幅
			cp->SetHeight(d);
			break;
		case 3:		// 全周 or Ｘ幅
			cp->SetRound(d);
			break;
		case 4:		// Ｒ
			cp->SetR(d);
			break;
		case 5:		// 位置
			WList.SetXPosition(ap->Pos, d);
			break;
		case 6:		// 横幅
			cp->SetWidthAll(d);
			break;
		case 7:		// 縦幅
			cp->SetHeightAll(d);
			break;
		case 8:		// 全周 or Ｘ幅
			cp->SetRoundAll(d);
			break;
	}
}
void CACal::SetParaLoad(AVAL *ap, double d)
{
	LDEF *lp = &AP->ldef[ap->Pos];
	if( (lp->TYPE == 0) && lp->A[0] && lp->B[0] ){		// 共振周波数を一定にする
		double w2 = 1/(lp->A[0] * lp->B[0]);
		if( ap->SubPos ){	// C
			lp->B[0] = d;
			lp->A[0] = 1/(w2 * d);
		}
		else {				// L
			lp->A[0] = d;
			lp->B[0] = 1/(w2 * d);
		}
	}
	else if( ap->SubPos ){	// C
		lp->B[0] = d;
	}
	else {					// L
		lp->A[0] = d;
	}
}
void CACal::SetParaFeed(AVAL *ap, double d)
{
	if( ap->SubPos ){
		AP->cdef[ap->Pos].EV = d;
	}
	else {
		AP->cdef[ap->Pos].DEG = d;
	}
}
void CACal::SetParaStack(AVAL *ap, double d){
	switch(ap->SubPos){
		case 0:
			AP->StackHW = AP->StackVW = d;
			break;
		case 1:
			AP->StackHW = d;
			break;
		case 2:
			AP->StackVW = d;
			break;
	}
}
double CACal::GetParaWire(AVAL *ap)
{
	WDEF *wp = &WList.wdef[ap->Pos];
	switch(ap->SubPos){
		case 0:
			return wp->Y1;
		case 1:
			return wp->Z1;
		case 2:
			return wp->Y2;
		case 3:
			return wp->Z2;
		case 4:
			return wp->R;
		case 5:
			return wp->X1 + WList.GetXAbs(ap->Pos);
		case 6:
			return wp->X2 + WList.GetXAbs(ap->Pos);
	}
	return 0.0;
}
// 極座標ワイヤ
double CACal::GetParaWireP(AVAL *ap)
{
	WDEF *wp = &WList.wdef[ap->Pos];
	double WL, XYD, YZD;
	GetWirePoll(WL, XYD, YZD, wp);
	switch(ap->SubPos){
		case 0:		// ワイヤ長（始点基準）
		case 1:		// ワイヤ長（終点基準）
		case 2:		// ワイヤ長（中心基準）
			return WL;
		case 3:		// 径度（始点基準）
		case 4:		// 径度（終点基準）
		case 5:		// 径度（中心基準）
			return XYD;
		case 6:		// 天頂角（始点基準）
		case 7:		// 天頂角（終点基準）
		case 8:		// 天頂角（中心基準）
			return YZD;
	}
	return 0.0;
}
double CACal::GetParaEle(AVAL *ap)
{
	CWGroup	*cp = &WList.List[ap->Pos];
	switch(ap->SubPos){
		case 0:		// 間隔
			return WList.Intval[ap->Pos];
		case 1:		// 横幅
		case 6:
			return cp->GetWidth();
		case 2:		// 縦幅
        case 7:
			return cp->GetHeight();
		case 3:		// 全周 or Ｘ幅
        case 8:
			return cp->GetRound();
		case 4:		// Ｒ
			return cp->GetR();
		case 5:		// 位置
			return WList.GetXPosition(ap->Pos);
	}
	return 0.0;
}
double CACal::GetParaLoad(AVAL *ap){
	if( ap->SubPos ){		// C
		return AP->ldef[ap->Pos].B[0];
	}
	else {					// L
		return AP->ldef[ap->Pos].A[0];
	}
}

double CACal::GetParaFeed(AVAL *ap){
	if( ap->SubPos ){
		return AP->cdef[ap->Pos].EV;
	}
	else {
		return AP->cdef[ap->Pos].DEG;
	}
}

double CACal::GetParaStack(AVAL *ap){
	if( ap->SubPos == 2 ){
		return AP->StackVW;
	}
	else {
		return AP->StackHW;
	}
}

void CACal::SetPara(int n, double d)
{
	aval[n].DC = d;
	switch(aval[n].Type){
		case avWIRE:
			SetParaWire(&aval[n], d);
			break;
		case avELE:
			SetParaEle(&aval[n], d);
			break;
		case avLOAD:
			SetParaLoad(&aval[n], d);
			break;
		case avHEIGHT:
			EP->antheight = d;
			break;
		case avFREQ:
			AP->cfq = d;
			atrg.bdef[0].fq = d;
			break;
		case avWIREP:
			SetParaWireP(&aval[n], d);
			break;
		case avFEED:
			SetParaFeed(&aval[n], d);
			break;
		case avSTACK:
			SetParaStack(&aval[n], d);
			break;
	}
}

void CACal::SetPara(int n)
{
	if( aval[n].With == -1 ){			// 独立変数の時
		SetPara(n, aval[n].DC);
		AVAL *ap = aval;
		int i;
		for( i = 0; i < amax; i++, ap++ ){
			if( ap->With == n ){
				SetPara(i, aval[n].DC);
			}
			else if( (-ap->With-2) == n ){
				SetPara(i, -aval[n].DC);
			}
			else if( (ap->With & 0x0000ffff) == n ){
				if( ap->With & 0x00010000 ){
					SetPara(i, aval[n].DC + ap->DW);
				}
				else if( ap->With & 0x00020000 ){
					SetPara(i, -aval[n].DC + ap->DW);
				}
				else if( ap->With & 0x00040000 ){
					SetPara(i, aval[n].DC * ap->DW);
				}
				else if( ap->With & 0x00080000 ){
					SetPara(i, aval[n].DC / ap->DW);
				}
			}
		}
	}
}
// 給電点の設定を行う
void CACal::SetBand(ANTDEF *ap, int n)
{
	if( ap->cmax > 4 ) return;

	CDEF *cp = atrg.bdef[n].cdef;
	ap->cfq = atrg.bdef[n].fq;
	for( ap->cmax = 0; cp->PLUS[0] && (ap->cmax < 4); cp++, ap->cmax++ ){
		memcpy(&ap->cdef[ap->cmax], cp, sizeof(CDEF));
	}
}

void CACal::SetNowCur(RESL *rp)
{
	atrg.CG = rp->GAIN;
	atrg.CFB = rp->FB;
	atrg.CRR = rp->R;
	atrg.CJX = rp->JX;
	atrg.CSWR = rp->SWR;
	atrg.CELV = rp->ELV;
}

// 評価値を得る
double CACal::CalcV(RESL *rp, CRes *cp)
{
	double V;

	if( atrg.TF ){
		double fb = rp->FB;
		if( fb > atrg.MaxFB ) fb = atrg.MaxFB + log(fb/atrg.MaxFB);
		fb *= atrg.TFB;
		double gain = rp->GAIN;
		if( gain > atrg.MaxGain ) gain = atrg.MaxGain + log(gain/atrg.MaxGain);
		gain *= atrg.TG;
		double jx = ABS(rp->JX);
		if( jx < atrg.MinJX ){
			jx = (atrg.MinJX - ((atrg.MinJX - jx)/20.0)) * atrg.TJX;
		}
		else {
			jx *= atrg.TJX;
		}
		jx = -jx;
		double swr = rp->SWR;
		if( swr < atrg.MinSWR ){
			swr = (atrg.MinSWR - ((atrg.MinSWR - swr)/20.0)) * atrg.TSWR;
		}
		else {
			swr = (swr - 1.0) * atrg.TSWR;
		}
		swr = -swr;
//		double swr = 1.0 - (rp->SWR * atrg.TSWR);
		double elv = -(rp->ELV * atrg.TELV);
		double mch = 0.0;
		if( atrg.TM ){
			double s;
			if( atrg.Match == 2 ){
				s = (atrg.TergR == NULLV) ? 1.0 : (rp->R - atrg.TergR);
				mch = (atrg.TergJX == NULLV) ? 1.0 : (rp->JX - atrg.TergJX);
				mch = -sqrt(4 * s * s + mch * mch);
			}
			else if( rp->R <= env.RO ){
				double s = sqrt((env.RO/rp->R)-1);
				mch = (rp->R * s);
				if( atrg.Match ){		// ヘアピン
					mch += rp->JX;
				}
				else {					// コンデンサ
					mch -= rp->JX;
				}
				mch = -ABS(mch);
			}
			else {
				s = 4 * env.RO * env.RO * rp->JX * rp->JX - 4 * (env.RO - rp->R) * env.RO * (rp->R*rp->R + rp->JX*rp->JX);
				if( s >= 0 ){
					s = sqrt(s);
					double b = -2 * env.RO * rp->JX;
					double v = 2 * (env.RO - rp->R);
					double MX1 = (b + s)/v;
					double MX2 = -(MX1 * rp->R * rp->R + (rp->JX + MX1)*rp->JX*MX1)/(rp->R*rp->R+(rp->JX+MX1)*(rp->JX+MX1));
					mch = -ABS(MX2);
				}
				else {
					mch = -rp->R;
				}
				mch -= 100.0;
			}
			mch *= atrg.TM;
		}
		double cur = 0.0;
		if( atrg.TI && atrg.IPLUS[0] ){
			int n = Str2PlusNo(AP, atrg.IPLUS);
			if( n ){
				atrg.CurCur = ABS(cp->Cur[n-1]);
				cur = atrg.IType ? -atrg.CurCur : atrg.CurCur;
				cur *= atrg.TI * 100;
			}
		}
		fb /= 10.0;
		jx /= 50.0;
		mch /= 50.0;
		V = gain + fb + jx + swr + elv + mch + cur;
	}
	else {
		V = atrg.V - 0.1;
		if( atrg.TI && atrg.IPLUS[0] ){
			int n = Str2PlusNo(AP, atrg.IPLUS);
			if( n ){
				atrg.CurCur = ABS(cp->Cur[n-1]);
			}
		}
	}
	return V;
}

void CACal::Init(ANTDEF *ap, ENVDEF *ep)
{
	AP = ap;
	EP = ep;
	WList.SetWire(ap);
}

int CACal::IsSameMax(void)
{
	AVAL *ap;
	int i;
	double *dp = atrg.AD;
	for( i = 0, ap = aval; i < amax; i++, ap++, dp++ ){
		if( ap->DC != *dp ) return FALSE;
	}
	return TRUE;
}

int CACal::WriteToFp(FILE *fp)		// セットアップのセーブ
{
	fwrite(&amax, 1, sizeof(amax), fp);
	if( amax ){
		fwrite(aval, 1, sizeof(aval), fp);
	}
	fwrite(&atrg, 1, sizeof(atrg), fp);
	fwrite(&PitchUnit, 1, sizeof(PitchUnit), fp);
	fwrite(&DegUnit, 1, sizeof(DegUnit), fp);

	fwrite(&mvmax, 1, sizeof(mvmax), fp);
	if( mvmax ){
		fwrite(&mvwp, 1, sizeof(mvwp), fp);
		fwrite(mval, 1, sizeof(mval), fp);
	}
	return ferror(fp) ? FALSE : TRUE;
}

int CACal::ReadFromFp(FILE *fp)		// セットアップのロード
{
	fread(&amax, 1, sizeof(amax), fp);
	if( amax ){
		fread(aval, 1, sizeof(aval), fp);
	}
	fread(&atrg, 1, sizeof(atrg), fp);
	fread(&PitchUnit, 1, sizeof(PitchUnit), fp);
	fread(&DegUnit, 1, sizeof(DegUnit), fp);

	fread(&mvmax, 1, sizeof(mvmax), fp);
	if( mvmax ){
		fread(&mvwp, 1, sizeof(mvwp), fp);
		fread(mval, 1, sizeof(mval), fp);
	}
	return ferror(fp) ? FALSE : TRUE;
}

void CACal::WriteMV(void)
{
	MVAL	*mp = &mval[mvwp];

	mp->V = atrg.V;
	double *dp = mp->AD;
	AVAL *ap = aval;
	int i;
	for( int i = 0; i < amax; i++, dp++, ap++ ){
		*dp = ap->DC;
	}
	mp->CG = atrg.CG;
	mp->CFB = atrg.CFB;
	mp->CRR = atrg.CRR;
	mp->CJX = atrg.CJX;
	mp->CSWR = atrg.CSWR;
	mp->CELV = atrg.CELV;
	float *pp;
	int N = 2/res.PtnF;
	for( pp = res.PtnH[2], i = 0; i < 180; i++, pp += N ){			// 水平パターンをコピー
		mp->PtnH[i] = ToFix(*pp);
	}
	for( pp = res.PtnV[2], i = 0; i <= 90; i++, pp += N ){			// 垂直パターンをコピー
		mp->PtnV[i] = ToFix(*pp);
	}
	mvwp++;
	if( mvwp >= MVMAX ) mvwp = 0;
	mvmax++;
	if( mvmax > MVMAX ) mvmax--;
}

int CACal::IsMV(double &max)
{
	AVAL	*ap;
	double	*dp;
	int i, j;
	MVAL	*mp = &mval[mvwp - 1];
	for( i = 0; i < mvmax; i++, mp-- ){
		if( mp < mval ) mp = &mval[MVMAX-1];
		dp = mp->AD;
		ap = aval;
		for( j = 0; j < amax; j++, dp++, ap++ ){
			if( *dp != ap->DC ){
				goto _nx;
			}
		}
		max = mp->V;
		return TRUE;
		_nx:;
	}
	return FALSE;
}

void CACal::ReadMV(MVAL *wp, int n)
{
	MVAL	*mp = &mval[mvwp - n - 1];
	if( mp < mval ) mp += MVMAX;
	memcpy(wp, mp, sizeof(MVAL));
}

int CACal::_GetLastChen(int c, int n)
{
	if( aval[n].With == -1 ){
		return n;
	}
	else {
		if( c >= amax ){
			return -1;
		}
		else {
			return _GetLastChen(c + 1, GetChenNo(aval[n].With));
		}
	}
}

int CACal::GetLastChen(int c, int n)
{
	int s = n;
	n = _GetLastChen(c, GetChenNo(n));
	if( n == -1 ) return -1;
	if( s < 0 ){
		n = - n - 2;
	}
	else if( s & 0x000f0000 ){
		n |= (s & 0x000f0000);
	}
	return n;
}

int CACal::InitPara(void)
{
	AVAL	*ap;
	int		i;

	mvwp = mvmax = 0;
	for( i = 0, ap = aval; i < amax; i++, ap++ ){
		if( ap->With != -1 ){
			if( (ap->With = GetLastChen(0, ap->With)) == -1 ){
				ErrorMB("変数(%d): 連携先の独立変数が見つかりません.", i+1);
				return FALSE;
			}
		}
		else {
			ap->DC = GetNowValue(i);
			if( !ap->DC && (((ap->Type==avELE)&&(ap->SubPos<5)) || (ap->Type==avLOAD)) ){
				ErrorMB("変数(%d): この変数は可変できません.", i+1);
				return FALSE;
			}
			atrg.AD[i] = -ap->DC;
			if( PitchUnit ){
				ap->DI = ap->DW;
			}
			else {
				ap->DI = (ap->DC * ap->DW) / 100.0;
			}
			ap->DI = ABS(ap->DI);
			ap->DIO = ap->DI;
		}
	}
	atrg.V = 1.0;
	atrg.VM = -MAXDOUBLE;
	atrg.AM = -MAXDOUBLE;
	atrg.CurCur = -1;
	if( !atrg.TF ) atrg.bmax = 1;
	for( i = 0; i < atrg.bmax; i++ ){
		BVM[i] = -MAXDOUBLE;
	}
	return TRUE;
}

void CACal::SetTradeOff(int gain, int fb, int jx, int swr, int elv, int mch, int cur)
{
	int dm = gain + fb + jx + swr + elv + mch + cur;
	if( !dm ) gain = fb = jx = swr = elv = mch = cur = 1;
	atrg.TG = double(gain);
	atrg.TFB = double(fb);
	atrg.TJX = double(jx);
	atrg.TSWR = double(swr);
	atrg.TELV = double(elv);
	atrg.TM = double(mch);
	atrg.TI = double(cur);
}

int CACal::Execute(void)
{
	int r = FALSE;
	if( amax ){
		r = Exec();
		for( int i = 0; i < amax; i++ ){
			SetPara(i, atrg.AD[i]);		// 最終値を設定する
		}
		WList.Update();
	}
	return r;
}

double CACal::GetNowValue(int n)
{
	switch(aval[n].Type){
		case avWIRE:
			return GetParaWire(&aval[n]);
		case avELE:
			return GetParaEle(&aval[n]);
		case avLOAD:
			return GetParaLoad(&aval[n]);
		case avHEIGHT:
			return EP->antheight;
		case avFREQ:
			return AP->cfq;
		case avWIREP:
			return GetParaWireP(&aval[n]);
		case avFEED:
			return GetParaFeed(&aval[n]);
		case avSTACK:
			return GetParaStack(&aval[n]);
	}
	return 0.0;
}

double CACal::GetNowValue(int n, double sc)
{
	if( n < 0 ){
		n = -n - 2;
		return -GetNowValue(n);
	}
	else if( n & 0x00010000 ){
		n &= 0x0000ffff;
		return (GetNowValue(n) + sc);
	}
	else if( n & 0x00020000 ){
		n &= 0x0000ffff;
		return (-GetNowValue(n) + sc);
	}
	else if( n & 0x00040000 ){
		n &= 0x0000ffff;
		return (GetNowValue(n) * sc);
	}
	else if( n & 0x00080000 ){
		n &= 0x0000ffff;
		return (GetNowValue(n) / sc);
	}
	else {
		return GetNowValue(n);
	}
}

void CACal::AdjSetup(int n)
{
	if( n >= AVMAX ) return;
	AVAL *ap = &aval[n];
	switch(ap->Type){
		case avWIRE:
			ap->DMAX = 2000.0;
			ap->DMIN = -2000.0;
			if( ap->Pos >= WList.wmax ){
				ap->Pos = WList.wmax - 1;
			}
			if( ap->SubPos >= 7 ){
				ap->SubPos = 0;
			}
			if( ap->SubPos == 4 ){
				ap->DMIN = 0.0;
				ap->DMAX = 0.5;
			}
			ap->DW = PitchUnit ? GetNormal(GetNowValue(n)/200.0) : 0.5;
			if( !ap->DW ) ap->DW = 0.1;
			break;
		case avELE:
			ap->DMAX = 2000.0;
			ap->DMIN = 0.0;
			if( ap->Pos >= WList.gmax ){
				ap->Pos = WList.gmax - 1;
			}
			if( ap->SubPos >= 9 ){
				ap->SubPos = 0;
			}
			if( ap->SubPos == 4 ){
				ap->DMIN = 0.0;
				ap->DMAX = 0.5;
			}
			ap->DW = PitchUnit ? GetNormal(GetNowValue(n)/200.0) : 0.5;
			if( (!ap->DW) && (ap->SubPos != 5) ) ap->DW = 0.1;
			break;
		case avLOAD:
			ap->DMAX = 10000.0;
			ap->DMIN = 0.0;
			if( ap->Pos >= AP->lmax ){
				ap->Pos = AP->lmax - 1;
			}
			if( ap->SubPos >= 2 ){
				ap->SubPos = 0;
			}
			ap->DW = PitchUnit ? GetNormal(GetNowValue(n)/200.0) : 0.5;
			if( !ap->DW ) ap->DW = 0.1;
			break;
		case avHEIGHT:
			ap->DMAX = 200.0;
			ap->DMIN = 0.0;
			ap->Pos = 0;
			ap->SubPos = 0;
			ap->DW = PitchUnit ? 1.0 : 10.0;
			break;
		case avFREQ:
			ap->DMAX = 1300.0;
			ap->DMIN = 1.5;
			ap->Pos = 0;
			ap->SubPos = 0;
			ap->DW = PitchUnit ? GetNormal(GetNowValue(n)/100.0) : 1.0;
			if( !ap->DW ) ap->DW = 0.1;
			break;
		case avWIREP:
			if( ap->Pos >= WList.wmax ){
				ap->Pos = WList.wmax - 1;
			}
			if( ap->SubPos >= 9 ){
				ap->SubPos = 0;
			}
			if( ap->SubPos <= 2 ){	// 長さ
				ap->DMAX = 2000.0;
				ap->DMIN = 0;
			}
			else {					// 角度
				ap->DMAX = 360.0;
				ap->DMIN = -360.0;
			}
			ap->DW = PitchUnit ? GetNormal(GetNowValue(n)/200.0) : 1.0;
			if( !ap->DW ) ap->DW = 0.1;
			break;
		case avFEED:
			if( ap->SubPos ){
				ap->DMIN = 0;
				ap->DMAX = 1.0;
				ap->DW = 0.01;
			}
			else {
				ap->DMAX = 360.1;
				ap->DMIN = -360.1;
				ap->DW = 1.0;
			}
			if( ap->Pos >= AP->cmax ){
				ap->Pos = AP->cmax - 1;
			}
			if( ap->SubPos > 1 ) ap->SubPos = 1;
			break;
		case avSTACK:
			ap->Pos = 0;
			ap->DMIN = 0.0;
			ap->DMAX = 2000.0;
			ap->DW = PitchUnit ? 0.01 : 1.0;
//			if( ap->SubPos > 1 ) ap->SubPos = 1;
			break;
	}
}

int CACal::Check(void)
{
	double	d;
	int i, j;
	AVAL *ap = aval;
	int r = TRUE;
	for( i = 0; i < amax; i++, ap++ ){
		d = GetNowValue(i);
		switch(ap->Type){
			case avWIRE:
				if( ap->Pos >= WList.wmax ){
					r = FALSE;
				}
				if( ap->SubPos >= 7 ){
					r = FALSE;
				}
				break;
			case avELE:
				if( ap->Pos >= WList.gmax ){
					r = FALSE;
				}
				if( ap->SubPos >= 9 ){
					r = FALSE;
				}
				if( !d && (ap->SubPos != 5)){
					ErrorMB("変数(%d): このパラメータは変更できません.", i + 1);
					return FALSE;
				}
				break;
			case avLOAD:
				if( ap->Pos >= AP->lmax ){
					r = FALSE;
				}
				if( ap->SubPos >= 2 ){
					r = FALSE;
				}
				if( AP->ldef[ap->Pos].TYPE == 2 ){
					ErrorMB("変数(%d): この集中定数は可変できません.", i + 1);
				}
				break;
			case avHEIGHT:
				if( !env.type ){
					ErrorMB("変数(%d): 自由空間なので地上高を変化させても意味はありません.", i + 1);
					return FALSE;
				}
				break;
		}
		if( r == FALSE ){
			ErrorMB("変数(%d): この変数は存在しません.", i + 1);
			return r;
		}
		for( j = 0; j < amax; j++ ){
			if( i != j ){
				if( (ap->Type == aval[j].Type)&&(ap->Pos == aval[j].Pos)&&(ap->SubPos==aval[j].SubPos) ){
					ErrorMB("変数(%d): 変数(%d)と重複しています.", i + 1, j+1);
					return FALSE;
				}
			}
		}
		if( ap->With != -1 ){
			if( RoundUpStr(d) != RoundUpStr(GetNowValue(ap->With, ap->DW)) ){
				if( YesNoMB("変数(%d): 連携先の変数(%d)と初期値が異なります.\r\n\r\n連携先の変数の値に強制設定されます。よろしいですか？", i+1, GetChenNo(ap->With)+1) != IDYES ) return FALSE;
			}
		}
		else {
			if( SetMinMax(ap, d) ) SetPara(i, d);
		}
	}
	return TRUE;
}

int CACal::SetMinMax(AVAL *ap, double &d)
{
	if( ap->With != -1 ) return 0;

	double	dd;
	if( ap->Max & 0x8000 ){
		dd = GetNowValue(ap->Max & 0x7fff);
		if( d > dd ){
			d = dd;
			return 1;
		}
	}
	else if( d >= ap->DMAX ){
		d = ap->DMAX - ap->DI;
		return 1;
	}
	if( ap->Min & 0x8000 ){
		dd = GetNowValue(ap->Min & 0x7fff);
		if( d < dd ){
			d = dd;
			return 1;
		}
	}
	else if( d <= ap->DMIN ){
		d = ap->DMIN + ap->DI;
		return 1;
	}
	return 0;
}

void CACal::SetTradeStr(LPSTR t)
{
	double	gain, fb, jx, swr, elv, mch, cur;
	gain = atrg.TG;
	fb = atrg.TFB;
	jx = atrg.TJX;
	swr = atrg.TSWR;
	elv = atrg.TELV;
	mch = atrg.TM;
	cur = atrg.TI;
	double dm = gain + fb + jx + swr + elv + mch + cur;
	if( dm && atrg.TF ){
		gain = (gain * 100.0)/dm;
		fb = (fb * 100.0)/dm;
		jx = (jx * 100.0)/dm;
		swr = (swr * 100.0)/dm;
		elv = (elv * 100.0)/dm;
		mch = (mch * 100.0)/dm;
		cur = (cur * 100.0)/dm;
		strcpy(t, "最適化 "); t += strlen(t);
		if( gain ){
			sprintf(t, " Gain:%s%%", StrDbl1(gain)); t += strlen(t);
		}
		if( fb ){
			sprintf(t, " F/B:%s%%", StrDbl1(fb)); t += strlen(t);
		}
		if( jx ){
			sprintf(t, " jX:%s%%", StrDbl1(jx)); t += strlen(t);
		}
		if( swr ){
			sprintf(t, " SWR:%s%%", StrDbl1(swr)); t += strlen(t);
		}
		if( elv ){
			sprintf(t, " Elv:%s%%", StrDbl1(elv)); t += strlen(t);
		}
		if( mch ){
			sprintf(t, " M:%s%%", StrDbl1(mch)); t += strlen(t);
		}
		if( cur ){
			sprintf(t, " C:%s%%", StrDbl1(cur));
		}
	}
	else {
		sprintf(t, "最適化 目標なし...(単純スイープ動作)");
	}

}
// CACalクラスの最適化の実行ループ
int CACal::Exec(void)
{
	int n, pf, f, init, mv, b;
	RESL *rp;
	// 一番最初のパラメータの設定
	SetBand(&MainWnd->ant, 0);		// 最初の給電情報を設定
	for( n = 0; n < amax; n++ ){
		SetPara(n);
	}
	AVAL *ap;
	double	MaxV = -MAXDOUBLE;
	double	MaxD;
	init = 0;
	int	N=1;
	int ContN;
	while(1){
		for( ap = aval, f = n = 0; n < amax; n++, ap++ ){
			if( ap->With == -1 ){		// 独立変数の時
				double	dir = 1.0;
				atrg.AM = MaxV;
				MaxD = ap->DC;
				if( ap->DI > ap->DIO ) ap->DI = ap->DIO;
				pf = 0;
				ContN = 0;
				while(1){
					if( init ){
						ap->DC += (ap->DI * dir);
						if( SetMinMax(ap, ap->DC) ){
							ap->DC = MaxD;				// 最大時の値に設定
							SetMinMax(ap, ap->DC);      // 調整
							if( dir >= 1.0 ){
								dir = -1;
								if( ap->DI > ap->DIO ) ap->DI = ap->DIO;
								ContN = 0;
								continue;
							}
							else {
								SetPara(n);
								break;
							}
						}
					}
					SetPara(n);
					if( IsSameMax() ){						// 組み合わせが最大時と同じ時
						atrg.V = atrg.VM;
						mv = TRUE;
					}
					else if( (mv=IsMV(atrg.V))==FALSE ){	// 記憶リストに存在しない時
						WList.Update();
						for( atrg.V = 0.0, b = 0; b < atrg.bmax; b++ ){
							if( atrg.bmax != 1 ) SetBand(&MainWnd->ant, b);
							if( MainWnd->ACalExecute() != TRUE ) return FALSE;
							rp = res.GetResP();
							if( !b ) SetNowCur(rp);
							BV[b] = CalcV(rp, &res);
							if( b == (atrg.bmax - 1) ){
								atrg.V = BV[0];
								for( int bb = 1; bb < atrg.bmax; bb++ ){
									if( atrg.bweight ){
										atrg.V += BV[b]/atrg.bmax;
									}
									else {
										atrg.V += BV[b];
									}
								}
							}
							if( exeenv.CalcDisp ){
								if( (N==1)||(!(N % 10)) ){
									if( (N != 1) && !(N % 400) ){
										MainWnd->CalMemo->Clear();
									}
									sprintf(InfoTTL, "%s Val  Para       R      jX    SWR   Ga    F/B   %s", (N >= 100) ? "   ":"  ", (atrg.CurCur < 0) ? "El":"Cur");
									LogPrint(InfoTTL);
								}
								sprintf(Info, "%2d %2d %9.4lf %6.1lf %6.1lf %6.2lf %5.2lf %5.2lf %4.1lf %c%s",
									N++, n+1, ap->DC,
									rp->R, rp->JX,
									rp->SWR, rp->GAIN, rp->FB,
									(atrg.CurCur < 0) ? rp->ELV : atrg.CurCur * 1000.0,
									(((b == (atrg.bmax - 1))&&(atrg.V > atrg.VM)) ? '*':' '),
									(atrg.bmax != 1) ? StrDbl(MainWnd->ant.cfq):""
								);
								LogPrint(Info);
								MainWnd->DrawPtnACalInfo();
							}
							if( (b != (atrg.bmax - 1)) && exeenv.CalcAbort ) return FALSE;
						}
						if( atrg.VM < atrg.V ){
							atrg.VM = atrg.V;
							for( int i = 0; i < amax; i++ ){	// 最大時のパラメータを記憶
								atrg.AD[i] = aval[i].DC;
							}
							maxres.CopyLastRes(&res);
							f = 1;
						}
					}
					if( mv == FALSE ) WriteMV();
					if( exeenv.CalcAbort ) return FALSE;
					if( MaxV < atrg.V ){
						MaxV = atrg.V;
						MaxD = ap->DC;
					}
					if( !atrg.TF ){
						init = 1;
						continue;
					}
					if( atrg.AM < atrg.V ){		// 増加傾向の時
						atrg.AM = atrg.V;
						if( init ){
							if( !pf ) pf = 1;
						}
						if( pf == 1 ){
							if( ContN >= 8 ){
								ap->DI = ap->DIO * 32.0;
							}
							else {
								if( ap->DI < (ap->DIO * 16.0) ) ap->DI = ap->DI * 2.0;
							}
						}
						else if( pf == 2 ){
							ap->DC = MaxD;				// 最大時の値に設定
							SetPara(n);
							break;
						}
					}
					else if( (pf == 1) && (ap->DI >= ap->DIO * 16.0) ){
						ap->DC = MaxD;
						ap->DI = ap->DI / 4;
						ContN = 0;
						pf = 2;
					}
					else if( pf ){				// 一旦増加を検出している時は終了
						ap->DC = MaxD;				// 最大時の値に設定
						SetPara(n);
						break;
					}
					else if( dir >= 1.0 ){		// ベクトルがプラスの時はマイナスに設定
						dir = -1;
						ap->DC = MaxD;				// 最初の値に戻す
						if( ap->DI > ap->DIO ) ap->DI = ap->DIO;
						ContN = 0;
					}
					else {
						ap->DC = MaxD;				// 最大時の値に設定
						SetPara(n);
						break;
					}
					init = 1;
					ContN++;
				}
			}
		}
		if( (!f) || (!atrg.TF) ) break;
	}
	return TRUE;
}
